import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Subscribing to Standard Business Central Events","description":"","frontmatter":{},"headers":[],"relativePath":"events/subscribing-to-standard-business-central-events.md","filePath":"events/subscribing-to-standard-business-central-events.md"}`),a={name:`events/subscribing-to-standard-business-central-events.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="subscribing-to-standard-business-central-events" tabindex="-1">Subscribing to Standard Business Central Events <a class="header-anchor" href="#subscribing-to-standard-business-central-events" aria-label="Permalink to “Subscribing to Standard Business Central Events”">​</a></h1><p>Business Central provides standard events that developers can subscribe to when they want to respond to existing application functionality.</p><p>Instead of modifying Microsoft&#39;s base application code, we create event subscribers in our extensions.</p><h2 id="example-customer-table-events" tabindex="-1">Example: Customer Table Events <a class="header-anchor" href="#example-customer-table-events" aria-label="Permalink to “Example: Customer Table Events”">​</a></h2><p>Business Central provides several standard table trigger events:</p><table tabindex="0"><thead><tr><th>Event</th><th>When it executes</th></tr></thead><tbody><tr><td><code>OnBeforeInsertEvent</code></td><td>Before a record is inserted.</td></tr><tr><td><code>OnAfterInsertEvent</code></td><td>After a record is inserted.</td></tr><tr><td><code>OnBeforeModifyEvent</code></td><td>Before a record is modified.</td></tr><tr><td><code>OnAfterModifyEvent</code></td><td>After a record is modified.</td></tr><tr><td><code>OnBeforeDeleteEvent</code></td><td>Before a record is deleted.</td></tr><tr><td><code>OnAfterDeleteEvent</code></td><td>After a record is deleted.</td></tr></tbody></table><h2 id="creating-a-subscriber" tabindex="-1">Creating a Subscriber <a class="header-anchor" href="#creating-a-subscriber" aria-label="Permalink to “Creating a Subscriber”">​</a></h2><p>Suppose we want to display a message whenever a new customer is inserted.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 CustomerSubscribers</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [EventSubscriber(</span></span>
<span class="line"><span>        ObjectType::Table,</span></span>
<span class="line"><span>        Database::Customer,</span></span>
<span class="line"><span>        &#39;OnAfterInsertEvent&#39;,</span></span>
<span class="line"><span>        &#39;&#39;,</span></span>
<span class="line"><span>        false,</span></span>
<span class="line"><span>        false)]</span></span>
<span class="line"><span>    local procedure AfterCustomerInsert(</span></span>
<span class="line"><span>        var Rec: Record Customer;</span></span>
<span class="line"><span>        RunTrigger: Boolean)</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;New customer created: %1&#39;, Rec.Name);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="understanding-the-code" tabindex="-1">Understanding the Code <a class="header-anchor" href="#understanding-the-code" aria-label="Permalink to “Understanding the Code”">​</a></h3><ul><li><code>ObjectType::Table</code>: We are subscribing to a table event.</li><li><code>Database::Customer</code>: The Customer table publishes the event.</li><li><code>OnAfterInsertEvent</code>: We want to respond after a record is inserted.</li><li><code>Rec</code>: Represents the customer record involved in the operation.</li><li><code>RunTrigger</code>: Indicates whether the table&#39;s <code>OnInsert</code> trigger was executed.</li></ul><p>Notice that we didn&#39;t create an event publisher or explicitly raise the event.</p><p>Business Central raises this system event automatically when the corresponding database operation occurs.</p><h2 id="discovering-standard-events" tabindex="-1">Discovering Standard Events <a class="header-anchor" href="#discovering-standard-events" aria-label="Permalink to “Discovering Standard Events”">​</a></h2><p>How do you know which events are available?</p><p>You can use:</p><ul><li><strong>VS Code IntelliSense:</strong> Helps discover available events and their parameters.</li><li><strong>AL Event Subscriber snippet:</strong> Type <code>teventsub</code> to generate subscriber syntax.</li><li><strong>Event Recorder:</strong> Records events raised while you perform operations in Business Central, helping you discover which events are triggered by a particular process.</li></ul><p>You can also inspect Microsoft&#39;s application source code and downloaded AL symbols.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>Business Central provides standard events for tables, pages and codeunits.</li><li>You can subscribe to these events without modifying Microsoft&#39;s base application.</li><li>Table events are particularly useful for responding to database operations.</li><li><code>OnBefore...</code> events allow you to execute logic before an operation.</li><li><code>OnAfter...</code> events allow you to execute logic after an operation.</li><li>Event Recorder helps discover which events are raised during application processes.</li></ul>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};